#!/usr/bin/env python3
"""libgcc dlopen scan: keep libgcc_dlopen_importers.toml honest (pkgs#1545 review).

glibc dlopens libgcc_s.so.1 to unwind on pthread_cancel, pthread_exit and
thrd_exit (and aborts without it), and backtrace() dlopens it too (it returns
no frames without it). A dlopen is not DT_NEEDED, so minimal's
missing-runtime_deps check cannot see it. libgcc_dlopen_guard.py checks, from
the recipes alone, that every package listed in libgcc_dlopen_importers.toml
has gcc-runtime's libgcc in its runtime closure. This script keeps that list
true: it reads every package's BUILT outputs and reports

  missing   a package whose ELFs import one of the symbols, not listed;
  stale     a listed package whose ELFs import none of them any more;
  changed   a listed package whose symbols or arches differ from the scan.

How it reads the outputs, with no build:

  1. Spec hashes come from the catalog dump (`mip dump -p --format json
     --arch <arch>`, one file per arch; the workflow uses the pinned evaluator
     from .github/actions/setup-mip).
  2. https://cache.minimal.dev/index.shisha maps spec hash -> artifact sha256
     (68-byte records: spec_hash[32] | flags[4] | sha256[32]).
  3. <cache>/<sha256>.zst is a zstd tar of the package's outputs. It is
     streamed through `zstd -dc` (never written to disk), its sha256 is
     checked against the index, and every ELF64 LE file's .dynsym is read for
     UNDEFINED imports of the symbols. A digest mismatch discards the result
     and counts as an error.

Cycle-breaker nodes (`<name> (prebuilt)`) and collections are skipped: they
are not packages a session installs by name.

Paths inside ELFs are evidence only. The check compares the package set, the
symbols and the arches; ELF paths drift with versions (libpython3.14 -> 3.15)
and are not compared.

Usage:
  libgcc_dlopen_scan.py --dump amd64=dump-amd64.json --dump arm64=dump-arm64.json
  libgcc_dlopen_scan.py ... --write .github/scripts/libgcc_dlopen_importers.toml

Exit codes: 0 = the data file matches the scan, 1 = it is out of date (or
--write changed it), 2 = UNVERIFIED (a dump or the index could not be read,
a download or digest failed, or too many packages had no artifact). 2 is
non-zero on purpose: a scan that could not see the fleet must not go green.

Needs `zstd` on PATH. Stdlib only (Python 3.11+ for tomllib).
"""

from __future__ import annotations

import argparse
import concurrent.futures
import hashlib
import json
import os
import struct
import subprocess
import sys
import tarfile
import threading
import time
import tomllib
import urllib.error
import urllib.request

SYMBOLS = ("backtrace", "pthread_cancel", "pthread_exit", "thrd_exit")
_SYMBOLS_B = {s.encode() for s in SYMBOLS}
DEFAULT_DATA = os.path.join(os.path.dirname(os.path.abspath(__file__)), "libgcc_dlopen_importers.toml")
INDEX_URL = "https://cache.minimal.dev/index.shisha"
CACHE_BASE = "https://cache.minimal.dev"
RECORD = 68
# More packages than this fraction without a cache artifact (per arch) means
# the scan did not see the fleet. Measured: ~1-3% miss on a built main.
MAX_MISS_FRACTION = 0.05
MAX_EVIDENCE = 5
UA = "gominimal-pkgs-libgcc-dlopen-scan"

HEADER = """\
# Packages whose shipped ELFs import a symbol for which glibc dlopens
# libgcc_s.so.1: pthread_cancel, pthread_exit, thrd_exit (unwinding; glibc
# aborts without libgcc_s) and backtrace (returns no frames without it).
# A dlopen is not DT_NEEDED, so missing-runtime_deps cannot see it
# (gominimal/pkgs#1545 review).
#
# .github/scripts/libgcc_dlopen_guard.py fails a PR when a package listed
# here has no gcc-runtime libgcc in its runtime closure. The fix is
#     subsetOf gcc-runtime ["libgcc"]
# in the package's runtime_deps (or in a runtime dep's).
#
# GENERATED by .github/scripts/libgcc_dlopen_scan.py --write from the built
# artifacts in the public cache; the weekly libgcc-dlopen-scan workflow fails
# when this file no longer matches them. `elfs` is evidence (at most 5 paths;
# `elf_count` is the total), not part of the check.
"""


# --- ELF ---------------------------------------------------------------------


def elf_imports(b: bytes) -> set[str] | None:
    """Undefined .dynsym names in `b` that are in SYMBOLS. None if `b` is not
    a 64-bit little-endian ELF (amd64 and arm64 are both ELF64 LE). Raises on
    a malformed file."""
    if b[:4] != b"\x7fELF" or len(b) < 64 or b[4] != 2 or b[5] != 1:
        return None
    (shoff,) = struct.unpack_from("<Q", b, 40)
    shentsize, shnum = struct.unpack_from("<HH", b, 58)
    if not shoff or not shnum:
        return set()
    secs = [struct.unpack_from("<IIQQQQIIQQ", b, shoff + i * shentsize) for i in range(shnum)]
    found: set[str] = set()
    for s in secs:
        if s[1] != 11:  # SHT_DYNSYM
            continue
        strtab = secs[s[6]]
        str_off, str_size = strtab[4], strtab[5]
        off, size, ent = s[4], s[5], s[9] or 24
        for j in range(size // ent):
            name, _info, _other, shndx = struct.unpack_from("<IBBH", b, off + j * ent)
            if shndx != 0 or not name or name >= str_size:
                continue
            start = str_off + name
            end = b.index(b"\0", start)
            sym = b[start:end]
            if sym in _SYMBOLS_B:
                found.add(sym.decode())
    return found


def scan_tar(stream) -> tuple[dict[str, set[str]], int, int]:
    """({elf path: symbols}, ELFs read, ELFs that failed to parse)."""
    hits: dict[str, set[str]] = {}
    elfs = bad = 0
    with tarfile.open(fileobj=stream, mode="r|") as t:
        for m in t:
            if not m.isfile():
                continue
            f = t.extractfile(m)
            head = f.read(4)
            if head != b"\x7fELF":
                continue
            b = head + f.read()
            try:
                syms = elf_imports(b)
            except Exception:  # noqa: BLE001 - untrusted bytes; counted, reported
                bad += 1
                continue
            if syms is None:
                continue
            elfs += 1
            if syms:
                hits[m.name.removeprefix("./")] = syms
    return hits, elfs, bad


# --- cache -------------------------------------------------------------------


class Miss(Exception):
    """The cache has no artifact for this spec hash."""


def fetch(url: str, timeout: int = 120):
    req = urllib.request.Request(url, headers={"User-Agent": UA})
    return urllib.request.urlopen(req, timeout=timeout)  # noqa: S310 - fixed https base


def load_index(url: str) -> dict[str, str]:
    with fetch(url) as r:
        data = r.read()
    if not data or len(data) % RECORD:
        raise ValueError(f"index is {len(data)} bytes, not a multiple of {RECORD}")
    return {data[i : i + 32].hex(): data[i + 36 : i + 68].hex() for i in range(0, len(data), RECORD)}


def scan_artifact(base: str, sha: str) -> tuple[dict[str, set[str]], int, int]:
    """Stream <base>/<sha>.zst through zstd into the tar scanner; check the digest."""
    try:
        resp = fetch(f"{base}/{sha}.zst")
    except urllib.error.HTTPError as e:
        if e.code == 404:
            raise Miss() from e
        raise
    proc = subprocess.Popen(["zstd", "-dcq"], stdin=subprocess.PIPE, stdout=subprocess.PIPE)
    h = hashlib.sha256()
    feed_err: list[BaseException] = []

    def feed() -> None:
        try:
            while True:
                chunk = resp.read(1 << 20)
                if not chunk:
                    break
                h.update(chunk)
                proc.stdin.write(chunk)
        except BaseException as e:  # noqa: BLE001 - re-raised below
            feed_err.append(e)
        finally:
            try:
                proc.stdin.close()
            except OSError:
                pass
            resp.close()

    t = threading.Thread(target=feed, daemon=True)
    t.start()
    try:
        result = scan_tar(proc.stdout)
    finally:
        while proc.stdout.read(1 << 20):  # drain past the tar end so the feeder finishes
            pass
        t.join()
        rc = proc.wait()
    if feed_err:
        raise feed_err[0]
    if h.hexdigest() != sha:
        raise ValueError(f"digest mismatch: got {h.hexdigest()}")
    if rc != 0:
        raise ValueError(f"zstd exited {rc}")
    return result


# --- data file ---------------------------------------------------------------


def load_data(path: str) -> dict[str, dict]:
    with open(path, "rb") as f:
        doc = tomllib.load(f)
    return doc.get("importers", {})


def _q(s: str) -> str:
    return json.dumps(s)  # a JSON string is a valid TOML basic string


def carried(
    found: dict[str, dict[str, dict[str, set[str]]]],
    listed: dict[str, dict],
    unscanned: dict[str, set[str]],
    arches: list[str],
) -> tuple[dict[str, dict], dict[str, set[str]]]:
    """What the scan could not read, kept from the committed file so that
    --write agrees with check mode (which treats it as unverified, not stale).
    (keep, extra_arches): keep = {pkg: committed entry} for a listed package
    with no artifact on any arch it is listed for; extra_arches = {pkg: listed
    arches with no artifact} for a scanned package."""
    keep: dict[str, dict] = {}
    extra: dict[str, set[str]] = {}
    for pkg, entry in listed.items():
        skipped = unscanned.get(pkg, set())
        listed_arches = set(entry.get("arches", arches))
        if pkg not in found:
            if listed_arches <= skipped:
                keep[pkg] = entry
        else:
            missing = (listed_arches & skipped) - set(found[pkg])
            if missing:
                extra[pkg] = missing
    return keep, extra


def render(
    found: dict[str, dict[str, dict[str, set[str]]]],
    keep: dict[str, dict] | None = None,
    extra_arches: dict[str, set[str]] | None = None,
) -> str:
    """found: {pkg: {arch: {path: symbols}}} -> the data file. keep and
    extra_arches (see carried()) hold what the scan could not read."""
    keep = {k: v for k, v in (keep or {}).items() if k not in found}
    extra_arches = extra_arches or {}
    out = [HEADER]
    for pkg in sorted(set(found) | set(keep)):
        out.append(f"\n[importers.{_q(pkg)}]")
        if pkg in keep:
            e = keep[pkg]
            out.append(f"symbols = [{', '.join(_q(s) for s in sorted(e.get('symbols', [])))}]")
            if "arches" in e:
                out.append(f"arches = [{', '.join(_q(a) for a in sorted(e['arches']))}]")
            out.append(f"elfs = [{', '.join(_q(p) for p in e.get('elfs', []))}]")
            out.append(f"elf_count = {int(e.get('elf_count', len(e.get('elfs', []))))}")
            continue
        per_arch = found[pkg]
        syms = sorted(set().union(*(s for paths in per_arch.values() for s in paths.values())))
        paths = sorted({p for paths in per_arch.values() for p in paths})
        arch_list = sorted(set(per_arch) | extra_arches.get(pkg, set()))
        out.append(f"symbols = [{', '.join(_q(s) for s in syms)}]")
        out.append(f"arches = [{', '.join(_q(a) for a in arch_list)}]")
        out.append(f"elfs = [{', '.join(_q(p) for p in paths[:MAX_EVIDENCE])}]")
        out.append(f"elf_count = {len(paths)}")
    return "\n".join(out) + "\n"


def compare(
    found: dict[str, dict[str, dict[str, set[str]]]],
    listed: dict[str, dict],
    unscanned: dict[str, set[str]],
    arches: list[str],
) -> tuple[list[str], list[str]]:
    """(problems, notes). unscanned: {pkg: arches with no artifact}."""
    problems, notes = [], []
    for pkg in sorted(set(found) - set(listed)):
        syms = sorted(set().union(*(s for p in found[pkg].values() for s in p.values())))
        ex = sorted(p for a in found[pkg].values() for p in a)[0]
        problems.append(
            f"missing: `{pkg}` imports {', '.join(syms)} ({ex}) but is not listed; "
            "re-run with --write, and give it `subsetOf gcc-runtime [\"libgcc\"]` if the guard asks"
        )
    for pkg in sorted(set(listed) - set(found)):
        skipped = unscanned.get(pkg, set())
        if set(listed[pkg].get("arches", arches)) <= skipped:
            # Every arch it imports on had no artifact: nothing contradicts it.
            notes.append(f"unverified: `{pkg}` is listed but has no artifact on {', '.join(sorted(skipped))}")
            continue
        problems.append(f"stale: `{pkg}` is listed but no shipped ELF imports {', '.join(SYMBOLS)}; re-run with --write")
    for pkg in sorted(set(listed) & set(found)):
        want = listed[pkg]
        syms = sorted(set().union(*(s for p in found[pkg].values() for s in p.values())))
        got_arches = sorted(found[pkg])
        if sorted(want.get("symbols", [])) != syms:
            problems.append(f"changed: `{pkg}` symbols listed {sorted(want.get('symbols', []))}, scanned {syms}")
        listed_arches = sorted(want.get("arches", []))
        # An arch with no artifact cannot contradict the listing.
        comparable = [a for a in listed_arches if a not in unscanned.get(pkg, set())]
        if sorted(set(got_arches) | (set(listed_arches) - set(comparable))) != listed_arches:
            problems.append(f"changed: `{pkg}` arches listed {listed_arches}, scanned {got_arches}")
    return problems, notes


# --- main --------------------------------------------------------------------


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n", 1)[0])
    ap.add_argument("--dump", action="append", required=True, metavar="ARCH=PATH", help="mip dump JSON per arch")
    ap.add_argument("--data", default=DEFAULT_DATA, help="importers TOML (default: next to this script)")
    ap.add_argument("--write", action="store_true", help="rewrite --data from the scan")
    ap.add_argument("--index-url", default=INDEX_URL)
    ap.add_argument("--cache-base", default=CACHE_BASE)
    ap.add_argument("--jobs", type=int, default=6)
    ap.add_argument("--only", default="", help="comma-separated packages (debugging; implies no stale check)")
    ap.add_argument("--max-miss-fraction", type=float, default=MAX_MISS_FRACTION)
    args = ap.parse_args(argv)

    dumps: dict[str, list[dict]] = {}
    try:
        for spec in args.dump:
            arch, _, path = spec.partition("=")
            if not path:
                raise ValueError(f"--dump wants ARCH=PATH, got {spec!r}")
            with open(path, encoding="utf-8") as f:
                text = f.read()
            # Some mip builds print log lines before the JSON array.
            at = text.find("\n[")
            dumps[arch] = json.loads(text if text.lstrip().startswith("[") else text[at + 1 :])
            if not dumps[arch]:
                raise ValueError(f"{path}: empty dump")
        index = load_index(args.index_url)
    except Exception as e:  # noqa: BLE001
        print(f"UNVERIFIED: {e}", file=sys.stderr)
        return 2
    only = {p for p in args.only.split(",") if p}

    jobs: list[tuple[str, str, str]] = []  # (arch, pkg, artifact sha)
    unscanned: dict[str, set[str]] = {}
    total: dict[str, int] = {}
    for arch, entries in dumps.items():
        total[arch] = 0
        for e in entries:
            name = e["name"]
            if " (" in name or e.get("is_collection"):
                continue
            if only and name not in only:
                continue
            total[arch] += 1
            sha = index.get(e["spec_hash"])
            if sha is None:
                unscanned.setdefault(name, set()).add(arch)
            else:
                jobs.append((arch, name, sha))

    found: dict[str, dict[str, dict[str, set[str]]]] = {}
    errors: list[str] = []
    bad_elfs: dict[str, int] = {}
    elfs_read = 0
    t0 = time.monotonic()

    def run(job):
        arch, name, sha = job
        last = None
        for attempt in range(3):
            try:
                return job, scan_artifact(args.cache_base, sha), None
            except Miss:
                return job, None, "miss"
            except Exception as e:  # noqa: BLE001
                last = e
                time.sleep(2 * (attempt + 1))
        return job, None, f"{type(last).__name__}: {last}"

    with concurrent.futures.ThreadPoolExecutor(max_workers=args.jobs) as ex:
        for n, ((arch, name, _sha), res, err) in enumerate(ex.map(run, jobs), 1):
            if err == "miss":
                unscanned.setdefault(name, set()).add(arch)
            elif err:
                errors.append(f"{name} ({arch}): {err}")
            else:
                hits, elfs, bad = res
                elfs_read += elfs
                if bad:
                    bad_elfs[f"{name} ({arch})"] = bad
                if hits:
                    found.setdefault(name, {})[arch] = hits
            if n % 50 == 0:
                print(f"... {n}/{len(jobs)} artifacts ({time.monotonic() - t0:.0f}s)", file=sys.stderr)

    lines = [f"## libgcc dlopen scan ({', '.join(f'{a}: {total[a]} packages' for a in sorted(total))}, {elfs_read} ELFs)\n"]
    unverified = []
    if errors:
        unverified.append(f"{len(errors)} artifact(s) failed to download or verify")
    for arch in sorted(total):
        missed = sorted(p for p, a in unscanned.items() if arch in a)
        if total[arch] and len(missed) > args.max_miss_fraction * total[arch]:
            unverified.append(f"{arch}: {len(missed)}/{total[arch]} packages have no cache artifact")
        if missed:
            lines.append(f"- {arch}: no cache artifact for {len(missed)}: {', '.join(missed)}")
    for k, v in sorted(bad_elfs.items()):
        lines.append(f"- {k}: {v} ELF(s) could not be parsed")
    for e in errors:
        lines.append(f"- error: {e}")

    # Build-only packages (libgcc_dlopen_build_only.toml, hand-maintained) run
    # in no box, so they are never listed; the guard checks that claim.
    build_only: set[str] = set()
    bo_path = os.path.join(os.path.dirname(os.path.abspath(args.data)), "libgcc_dlopen_build_only.toml")
    if os.path.exists(bo_path):
        with open(bo_path, "rb") as f:
            build_only = set((tomllib.load(f).get("build_only") or {}).keys())
        for pkg in sorted(build_only & set(found)):
            lines.append(f"- build-only, not listed: `{pkg}`")
            del found[pkg]

    status = 0
    if unverified:
        lines.append(f"\nUNVERIFIED: {'; '.join(unverified)}")
        status = 2
    elif args.write:
        if only:
            print("refusing --write with --only: it would drop every other package", file=sys.stderr)
            return 2
        old = open(args.data, encoding="utf-8").read() if os.path.exists(args.data) else ""
        try:
            listed = load_data(args.data) if old else {}
        except Exception as e:  # noqa: BLE001
            print(f"UNVERIFIED: cannot read {args.data}: {e}", file=sys.stderr)
            return 2
        # An unscanned package keeps its committed entry, as check mode does.
        keep, extra = carried(found, listed, unscanned, sorted(dumps))
        keep = {k: v for k, v in keep.items() if k not in build_only}
        new = render(found, keep, extra)
        if new != old:
            with open(args.data, "w", encoding="utf-8") as f:
                f.write(new)
            kept = f" ({len(keep)} unscanned, kept as committed)" if keep else ""
            lines.append(f"\nWROTE {args.data}: {len(found) + len(keep)} importers{kept}")
            status = 1
        else:
            lines.append(f"\nUP TO DATE: {len(found)} importers")
    else:
        try:
            listed = load_data(args.data)
        except Exception as e:  # noqa: BLE001
            print(f"UNVERIFIED: cannot read {args.data}: {e}", file=sys.stderr)
            return 2
        if only:
            listed = {k: v for k, v in listed.items() if k in only}
        problems, notes = compare(found, listed, unscanned, sorted(dumps))
        for n_ in notes:
            lines.append(f"- {n_}")
        if problems:
            lines.append(f"\nOUT OF DATE: {len(problems)} problem(s); {len(found)} importers scanned, {len(listed)} listed")
            for p in problems:
                lines.append(f"- {p}")
                print(f"::error title=libgcc dlopen scan::{p}")
            # The regenerated file, so the fix is a copy-paste (or run --write).
            lines.append("\n<details><summary>Regenerated libgcc_dlopen_importers.toml</summary>\n")
            keep, extra = carried(found, listed, unscanned, sorted(dumps))
            keep = {k: v for k, v in keep.items() if k not in build_only}
            lines.append("```toml\n" + render(found, keep, extra) + "```\n</details>")
            status = 1
        else:
            lines.append(f"\nUP TO DATE: {len(found)} importers")
    text = "\n".join(lines) + "\n"
    print(text)
    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary:
        with open(summary, "a", encoding="utf-8") as f:
            f.write(text)
    return status


if __name__ == "__main__":
    sys.exit(main())
